{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C50"],
      "claim": "Pethidine, a close opioid analgesic analogue, showed 60% oral bioavailability in a patient, directly supporting F ≥20% for the query opioid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Samidorphan, a morphinan opioid antagonist sharing the 14-hydroxy/6-keto morphinan core, had absolute oral bioavailability of 68.6% in humans, strongly supporting high oral F for oxycodone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Meperidine absolute oral bioavailability ranged from 47% to 73% in healthy men, supporting high oral bioavailability for the query opioid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Pentazocine, a benzomorphan opioid, had absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold; this is contradictory but structurally less aligned with the 3-methoxy-14-hydroxy-6-keto morphinan of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C56"],
      "claim": "Meptazinol, another opioid, had absolute oral bioavailability of 8.69%, showing that some opioids can be low; however, its non-morphinan phenol structure limits transfer to oxycodone.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is oxycodone, a 4,5-epoxymorphinan opioid. The most structurally relevant evidence—samidorphan (morphinan, 14-OH/6-keto, F≈69%) and pethidine/meperidine (opioid, F≈50–60%)—supports high oral bioavailability. Low-F opioid analogues (meptazinol, pentazocine) are less structurally aligned and are outweighed. Prediction: high (F≥20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for oxycodone is present in the supplied records; the decision relies on structurally related analogues.",
    "Low-F opioids demonstrate that first-pass metabolism can be structure-dependent, so direct human F data for oxycodone would further reduce residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

